// Golden packets and malformed synthetic readbacks; pure managed code only.
using System;
using System.Collections.Generic;
using System.Linq;
using RogControl;

public static class MouseButtonActionProtocolTests {
 static int checks;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception(label);}
 static Dictionary<string,object> Map(params object[] items){var map=new Dictionary<string,object>();for(int i=0;i<items.Length;i+=2)map.Add((string)items[i],items[i+1]);return map;}
 static Dictionary<string,object> Snapshot(){var normal=new Dictionary<string,object>();var shift=new Dictionary<string,object>();string[] sources={"leftButton","rightButton","middleButton","sideKeyLeftBackward","sideKeyLeftForward","dpi1","scrollUp","scrollDown"};int[] codes={496,497,498,484,485,486,488,489};var names=MouseButtonActionFacts.SimpleTargetMap();for(int i=0;i<sources.Length;i++){normal.Add(sources[i],Map("target",names.Single(item=>item.Value==codes[i]).Key,"targetCode",codes[i]));shift.Add(sources[i],Map("target","MouseClickLeft","targetCode",496));}return Map("buttonBindings",normal,"shiftButtonBindings",shift);}
 static Dictionary<string,object> Bank(Dictionary<string,object> state,bool shift=false){return (Dictionary<string,object>)state[shift?"shiftButtonBindings":"buttonBindings"];}
 static Dictionary<string,object> Binding(Dictionary<string,object> state,string source,bool shift=false){return (Dictionary<string,object>)Bank(state,shift)[source];}
 static byte[] Packet(Dictionary<string,object> before,string source,string target,bool shift=false){byte[] packet;bool same;Check(MouseButtonActionFacts.TrySimplePacket(7548,before,source,target,shift,out packet,out same)&&!same&&packet!=null,"prepared changed single-field packet");return packet;}
 public static int Main(){try{Run();return 0;}catch(Exception error){Console.Error.WriteLine(error.Message);return 1;}}
 static void Run(){
  var known=MouseButtonActionFacts.SimpleTargetMap();Check(known.Count==87&&known.Values.Distinct().Count()==87,"existing 87 names are unique, no fabricated aliases or new raw codes");Check(MouseButtonActionFacts.Targets("keyboard").Length==65,"keyboard exposure is limited to existing 65 exact single-key codes");Check(MouseButtonActionFacts.Targets("media").Length==7,"seven direct media codes only");Check(MouseButtonActionFacts.Targets("mouse").Length==10,"ten visible original mouse functions only");
  Check(known["KeyA"]==4&&known["Digit0"]==39&&known["F4"]==61&&known["LeftCtrl"]==224,"single map uses native keyboard usages, not Windows VK values");Check(known["MultimediaVolumeUp"]==246&&known["ShiftMode"]==253,"media and Shift retain vendor action codes");
  foreach(string category in new[]{"macro","windows","armoury","text","screenshot","unknown",""})Check(MouseButtonActionFacts.Targets(category).Length==0,"unimplemented software category has no hardware actions");
  foreach(int pid in new[]{7546,7548})Check(MouseButtonActionFacts.PreparedModel(pid)&&!MouseButtonActionFacts.FirmwareChordPreparedModel(pid),"P725 scalar protocol is prepared; shared generic chord methods do not enable firmware chords");foreach(int pid in new[]{0,7549,7588,7489,7547,65535})Check(!MouseButtonActionFacts.PreparedModel(pid)&&!MouseButtonActionFacts.FirmwareChordPreparedModel(pid),"unverified model gets no action or chord capability");
  var before=Snapshot();Check(Packet(before,"leftButton","KeyA").SequenceEqual(new byte[]{0x51,0x21,0,0,0xF0,1,4,0}),"golden ordinary keyboard A packet");Check(Packet(before,"sideKeyLeftForward","MultimediaVolumeUp",true).SequenceEqual(new byte[]{0x51,0x23,0,0,0xE5,1,0xF6,0}),"golden independent Shift-bank volume up packet");Check(Packet(before,"sideKeyLeftForward","ShiftMode").SequenceEqual(new byte[]{0x51,0x21,0,0,0xE5,1,0xFD,0}),"golden normal-bank SpeedShift trigger packet");
  foreach(string category in new[]{"keyboard","media"})foreach(string target in MouseButtonActionFacts.Targets(category))foreach(bool shift in new[]{false,true}){byte[] packet;bool same;Check(MouseButtonActionFacts.TrySimplePacket(7546,before,"sideKeyLeftForward",target,shift,out packet,out same)&&!same&&packet.Length==8,"exact scalar action builds in either independently read bank");Check((packet[6]|packet[7]<<8)==known[target]&&packet[1]==(shift?35:33),"little-endian code and bank command remain exact");Check(MouseButtonActionFacts.MatchesSimple(before,"sideKeyLeftForward",target,shift)==false,"prior different raw mapping does not claim confirmed application");var readback=Snapshot();Binding(readback,"sideKeyLeftForward",shift)["targetCode"]=known[target];Binding(readback,"sideKeyLeftForward",shift)["target"]=target;Check(MouseButtonActionFacts.MatchesSimple(readback,"sideKeyLeftForward",target,shift)==true,"changed valid readback confirms scalar application");}
  byte[] ignored;bool sameState;Check(MouseButtonActionFacts.TrySimplePacket(7548,before,"leftButton","MouseClickLeft",false,out ignored,out sameState)&&sameState&&ignored==null,"same target returns alreadySet without a write packet");
  foreach(string source in new[]{"leftButton","scrollUp","scrollDown"})Check(!MouseButtonActionFacts.TargetAllowed(before,source,"ShiftMode",false),"protected left-click and scroll controls cannot become trigger");foreach(string source in new[]{"rightButton","middleButton","sideKeyLeftBackward","sideKeyLeftForward","dpi1"}){Check(MouseButtonActionFacts.TargetAllowed(before,source,"ShiftMode",false),"eligible normal source can be the one trigger");Check(!MouseButtonActionFacts.TargetAllowed(before,source,"ShiftMode",true),"Shift layer cannot recursively trigger itself");}
  var existing=Snapshot();Binding(existing,"rightButton")["target"]="ShiftMode";Binding(existing,"rightButton")["targetCode"]=253;Check(!MouseButtonActionFacts.TargetAllowed(existing,"sideKeyLeftForward","ShiftMode",false),"another active trigger blocks implicit multi-button changes");Check(MouseButtonActionFacts.TrySimplePacket(7548,existing,"rightButton","ShiftMode",false,out ignored,out sameState)&&sameState&&ignored==null,"same current trigger is a safe no-op");
  foreach(string source in new[]{"scrollUp","scrollDown"})Check(!MouseButtonActionFacts.TargetAllowed(before,source,"MouseTargetFocus",false),"sniper hold action cannot be assigned to wheel events");
  foreach(string missing in new[]{"buttonBindings","shiftButtonBindings"}){var partial=Snapshot();partial[missing]=null;bool shift=missing=="shiftButtonBindings";Check(!MouseButtonActionFacts.TrySimplePacket(7548,partial,"leftButton","KeyA",shift,out ignored,out sameState),"missing selected bank blocks write");Check(MouseButtonActionFacts.TrySimplePacket(7548,partial,"leftButton","KeyA",!shift,out ignored,out sameState),"independent fully read opposite bank remains usable");}
  foreach(string source in new[]{"leftButton","rightButton","middleButton","sideKeyLeftBackward","sideKeyLeftForward","dpi1","scrollUp","scrollDown"}){var partial=Snapshot();Bank(partial).Remove(source);Check(!MouseButtonActionFacts.CompleteBank(partial,false)&&!MouseButtonActionFacts.TrySimplePacket(7548,partial,"sideKeyLeftForward","KeyA",false,out ignored,out sameState),"incomplete full mapping cannot become writable");}
  foreach(object invalid in new object[]{null,-1,65536,"496",496.0,true}){var invalidBank=Snapshot();Binding(invalidBank,"leftButton")["targetCode"]=invalid;Check(!MouseButtonActionFacts.CompleteBank(invalidBank,false),"invalid typed code anywhere invalidates the full bank");}
  var zero=Snapshot();Binding(zero,"leftButton")["targetCode"]=0;Binding(zero,"leftButton")["target"]=null;Check(MouseButtonActionFacts.CompleteBank(zero,false),"zero remains a readable raw code without a guessed assignment");Check(!MouseButtonActionFacts.TrySimplePacket(7548,zero,"leftButton","KeyA",false,out ignored,out sameState),"unknown zero baseline cannot be overwritten through fabricated default");Check(MouseButtonActionFacts.MatchesSimple(zero,"leftButton","KeyA",false)==false,"read zero differs from actual A code");
  foreach(string invalid in new[]{null,"","rawCode","Macro","WindowsCloseApp","MuteMicrophone","KeyDisabled","MouseProfile"})Check(!MouseButtonActionFacts.TrySimplePacket(7548,before,"sideKeyLeftForward",invalid,false,out ignored,out sameState),"unimplemented and unlisted UI target rejected by pure encoder");
  Check(MouseButtonActionFacts.Caption("MultimediaMute")=="关闭声音"&&MouseButtonActionFacts.Caption("MultimediaPlayPause")=="播放/暂停","media labels retain installed Simplified Chinese words");Console.WriteLine("Mouse button actions: "+checks+" pure protocol checks; no native/GET/SET.");
 }
}
